export const DEV_DEPENDENCIES = {
  eslint: '^9.0.0',
  '@eslint/js': '^9.0.0',
  'typescript-eslint': '^8.12.2',
  typescript: '^5.6.3',
  globals: '^16.0.0',
  prettier: '^3.6.2',
  'eslint-config-prettier': '^10.0.0',
  husky: '^9.1.6',
  'lint-staged': '^15.2.10',
  '@commitlint/cli': '^19.5.0',
  '@commitlint/config-conventional': '^19.5.0',
  commitizen: '^4.3.1',
  'cz-customizable': '^7.2.1'
}
import fs from 'fs'
import os from 'os'
import path from 'path'

export function createFileTransaction(targetPaths) {
  const backupRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'commit-pack-rollback-'))
  const uniqueTargets = [...new Set(targetPaths.map((target) => path.resolve(target)))]
  const entries = uniqueTargets.map((target, index) => {
    const existed = fs.existsSync(target)
    const backupPath = path.join(backupRoot, String(index))

    if (existed) {
      fs.cpSync(target, backupPath, {
        recursive: true,
        preserveTimestamps: true
      })
    }

    return { target, existed, backupPath }
  })

  let closed = false

  const cleanup = () => {
    fs.rmSync(backupRoot, { recursive: true, force: true })
    closed = true
  }

  return {
    commit() {
      if (!closed) cleanup()
    },

    rollback() {
      if (closed) return

      for (const entry of entries) {
        fs.rmSync(entry.target, { recursive: true, force: true })
        if (entry.existed) {
          fs.mkdirSync(path.dirname(entry.target), { recursive: true })
          fs.cpSync(entry.backupPath, entry.target, {
            recursive: true,
            preserveTimestamps: true
          })
        }
      }

      cleanup()
    }
  }
}
import chalk from 'chalk'
import { execFileSync } from 'child_process'
import { isMonorepoRoot } from './projectUtils.mjs'

export function getInstallCommand(
  dependencies,
  packageManager,
  { installAtWorkspaceRoot = false } = {}
) {
  const packages = Array.isArray(dependencies) ? dependencies : [dependencies]
  const commands = {
    pnpm: {
      command: 'pnpm',
      args: ['add', ...(installAtWorkspaceRoot ? ['-w'] : []), '-D', ...packages]
    },
    yarn: { command: 'yarn', args: ['add', ...packages, '--dev'] },
    bun: { command: 'bun', args: ['add', '-d', ...packages] },
    npm: { command: 'npm', args: ['install', ...packages, '--save-dev'] }
  }
  if (!commands[packageManager]) throw new Error(`不支持的包管理器: ${packageManager}`)
  return commands[packageManager]
}

export function installWithProgress(
  dependencies,
  packageManager,
  projectRoot,
  { isWorkspace = false } = {}
) {
  if (!dependencies?.length) {
    console.log(chalk.yellow('✅ 所有开发依赖已声明，跳过安装'))
    return
  }
  const installAtWorkspaceRoot =
    packageManager === 'pnpm' && !isWorkspace && isMonorepoRoot(projectRoot)
  const { command, args } = getInstallCommand(dependencies, packageManager, {
    installAtWorkspaceRoot
  })
  console.log(`⬇️ 一次安装 ${dependencies.length} 个开发依赖...`)
  execFileSync(command, args, { cwd: projectRoot, stdio: 'inherit' })
  console.log(chalk.green('✅ 依赖安装完成'))
}

