function runWorkspaceInitializer(gitRoot) {
  return spawnSync(process.execPath, [path.resolve('bin/index.mjs'), '--workspace=@example/web'], {
    cwd: gitRoot,
    env: { ...process.env, INIT_CWD: gitRoot },
    encoding: 'utf8',
    timeout: 10000
  })
